pub struct Solution;

impl Solution {
    pub fn divide(dividend: i32, divisor: i32) -> i32 {
        if dividend == i32::MIN && divisor == -1 {
            return i32::MAX;
        }
        if divisor == 1 {
            return dividend;
        }
        if divisor == -1 {
            return -dividend;
        }

        let negative = (dividend < 0) ^ (divisor < 0);

        let mut a = if dividend < 0 { dividend } else { -dividend };
        let b = if divisor < 0 { divisor } else { -divisor };

        let half_min = i32::MIN >> 1;
        let mut multiples = [0i32; 32];
        let mut powers = [0i32; 32];
        let mut count = 0;

        let mut cur_val = b;
        let mut cur_power = -1;

        while cur_val >= a {
            multiples[count] = cur_val;
            powers[count] = cur_power;
            count += 1;
            if cur_val < half_min {
                break;
            }
            cur_val += cur_val;
            cur_power += cur_power;
        }

        let mut quotient = 0i32;
        for i in (0..count).rev() {
            if a <= multiples[i] {
                a -= multiples[i];
                quotient += powers[i];
            }
        }

        if negative { quotient } else { -quotient }
    }
}

